window.RP_SESSION={"id":"S-682bfc6150c3","messages":[{"id":"RP-II-0098158","time":"2026-05-07T15:18:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098159","time":"2026-05-07T15:18:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098160","time":"2026-05-07T15:18:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098161","time":"2026-05-07T15:18:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"숲.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098162","time":"2026-05-07T15:19:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드 앗질랄 아스사피 빈 칼리드 알 쿠라이시는 숲이라는 환경에 그렇게 익숙하진 않다. 그의 고향 스카일라는 저주받은 모래와 바위의 사막으로 가득한 척박한 땅.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098163","time":"2026-05-07T15:19:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래. 라슈로 녀석이 그렇게도 바꾸고 싶어 했던...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098164","time":"2026-05-07T15:21:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n길드 뒷편 숲은 검은 갑주의 기사가 길을 찾기 그닥 좋은 환경이 아니다. 짐승이 가는 길과 사람이 가는 길을 헷갈리고 만 사막의 범은 길을 찾는 법을 잘 모르고 그만 헤매이는 신세가 되고 말았다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098165","time":"2026-05-07T15:21:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여기가 어디야... \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098166","time":"2026-05-07T15:23:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"@자이라","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098167","time":"2026-05-07T15:27:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"길이라도 잃으신 겁니까?\"\n\n\"아, 잃고 싶어 오신 건가. 그런 꼴로 누가 숲에 들어오겠어, 그대.\"\n\n이 여자가 비록 인두겁을 쓴 개자식으로 평가받을 지언정, 헤매는 사람을 외면할 정도로 인정이 없는 것은 아니었다. 자이라의 인정은 줄곧 변덕이라는 훌륭한 이유를 동반했다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098168","time":"2026-05-07T15:27:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"괜한 오지랖이라 하면 물러나지.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098169","time":"2026-05-07T15:28:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n아, 길드원이다. 그것도 본 적 있는 드루이드. 살았다.\n\n\" 도와... \"\n\n성기사의 자존심이 도움을 용납할까?","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098170","time":"2026-05-07T15:28:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 주시오. \"\n\n용납했다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098171","time":"2026-05-07T15:29:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드 알 쿠라이시는 검은 건틀릿으로 덮인 커다란 손을 내민다. 이래서 숲속에 들어갈 때는 사냥꾼이나 드루이드가 있어야 해.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098172","time":"2026-05-07T15:31:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"손을 바라본다. 그리고 님드의 눈(그것이 있을 곳으로 추정되는 구멍)을 본다. 두 번 정도 시선이 왕복했다.\n\n\"우선, 손은 다시 내려도 좋을 것 같다만.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098173","time":"2026-05-07T15:33:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"여기 온 목적이 무어야. 그냥 밤 산책이라면 돌아가는 길은 안내해 줄 수 있어.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098174","time":"2026-05-07T15:34:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"용무가 있었다면 뭐...\"\n\n흠, 하고 짧은 숨 뱉으며 어깨 으쓱였다. 알아서 하시고.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098175","time":"2026-05-07T15:35:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 밤 산책도 할 겸. 열매라도 따서 가져갈까 했소만은... \"\n\n왼손 위에 다소곳이 올려져 있는 한 줌의 산딸기.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098176","time":"2026-05-07T15:35:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 보다시피 성과는 없고 길만 잃었소. \"\n\n한 입 털어넣으면 끝날 양이다...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098177","time":"2026-05-07T15:39:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"자이라는,\n\n—손을 내밀었다.\n제법 당당하게.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098178","time":"2026-05-07T15:40:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"안내비로 받으면 딱 좋겠군. 가지.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098179","time":"2026-05-07T15:40:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"칫.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098180","time":"2026-05-07T15:40:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"자이라의 손에 겨우 구한 한 줌의 산딸기를 건내주고.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098181","time":"2026-05-07T15:40:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 맛있게 드시오. \"\n\n그녀를 따라간다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098182","time":"2026-05-07T15:40:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"갑옷 속에서 뭐라고 속삭이는 것 같지만 밖으로는 들리지 않는다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098183","time":"2026-05-07T15:41:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"그렇다. 벼룩의 간도 모으면 태산이다.\n\n\"그나저나 그대, 갑옷 정도는 벗는 것이 좋지 않겠어?\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098184","time":"2026-05-07T15:42:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"고작 산딸기 한 줌, 그니까 님드의 수확물 전부를 얻어내고, 꽤 기분이 좋아진 탓에 걸음이 유난히 가벼웠다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098185","time":"2026-05-07T15:43:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"앞에서 걷다가 발 한 쪽을 축으로 삼아 빙글, 님드 마주했을 것이다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098186","time":"2026-05-07T15:43:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 벗을 수 없소. \"\n\n내 산딸기...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098187","time":"2026-05-07T15:44:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"욕을 하고 싶었다면 목소리를 키우는 걸 추천하지.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098188","time":"2026-05-07T15:44:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"당신의 가벼운 걸음을 무겁게 따라가다가 당신이 자신과 마주보자 흠칫 놀라지만.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098189","time":"2026-05-07T15:44:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"당신이 이내 자신이 속삭이는걸 들어서라는 사실을 알고.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098190","time":"2026-05-07T15:45:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 욕 한 적 없소... \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098191","time":"2026-05-07T15:49:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"그래, 그래, 믿네.\"\n\n\"산딸기 건에는 진심으로 감사를 표하겠어.\"\n\n당연하지만 둘 모두 빈말이었다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098192","time":"2026-05-07T15:50:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"오랜만에 먹으니 제법 좋군. 그대 돌려보내고 나면 산딸기나 더 따갈까 싶어.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098193","time":"2026-05-07T15:51:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 목숨 구해준 값인데, 뭘. \"\n\n그러고는 또 갑옷 속에서 꿍얼꿍얼.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098194","time":"2026-05-07T15:51:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드가 자이라를 따라가자 그리 많이 가지도 않았는데 저 멀리서 길드의 불빛 같은게 보인다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098195","time":"2026-05-07T15:51:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 이렇게 가까웠다고... \"\n\n이렇게 가까웠는데 길을 잃었다고.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098196","time":"2026-05-07T15:53:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"생명의 은인이라...\"\n\n...이런 근방에서 길을 잃은 당신이 모지리 아닐지.\n\n말은 삼켰지만 눈빛에서 말하고자 했던 것이 선하다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098197","time":"2026-05-07T15:55:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098198","time":"2026-05-07T15:55:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"......목숨을 구했으니 나중에 더 큰 걸로 답례하길 바라지.\"\n\n농 던지며 고개 절레절레 젓는다. 저어 앞에 길드 손가락으로 짚어보이고,","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098199","time":"2026-05-07T15:55:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"문 앞까지 데려다 주어야 할까 고민이야.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098200","time":"2026-05-07T15:55:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"그대가 길을 잃기 충분한 거리 아닌가.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098201","time":"2026-05-07T15:56:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 내가 살던 곳은 다 사막이었소... \"\n\n젠장. 바보 보듯 하는 눈빛... 하지만 여기서 길을 잃은건 바보 같은 행동이 맞아서 할 수 있는 변명은 겨우 이런 것 뿐.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098202","time":"2026-05-07T15:59:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"나도 사막 출신이네만.\"\n\n입꼬리 한 쪽이 슬슬 올라가는 걸 숨길 생각조차 없었다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098203","time":"2026-05-07T16:00:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"다음부터는 빛나는 조약돌이라도 주워다가 흘리고 다니게.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098204","time":"2026-05-07T16:00:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"헨*과 그*텔처럼.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098205","time":"2026-05-07T16:05:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n더 이상 변명거리가 없다. 젠장. 이러면 그냥 이 고고한 성기사가 바보짓을 한게 맞잖아!","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098206","time":"2026-05-07T16:06:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"내가 애도 아니고... 라고 말하려다, 숲으로 가득한 이 온대의 나라에서는 애들도 집 뒤 숲에서 길을 잃지는 않으리라는 생각이 든다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098207","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"저벅저벅 길드를 향해 걸어가는데...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098208","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098209","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 지능 판정 :\n[2] + [0] = [2]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0098210","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"길 중 하나는 길드로 가는 곳 같은데.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098211","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"흠.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098212","time":"2026-05-07T16:09:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모르겠다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098213","time":"2026-05-07T16:10:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098214","time":"2026-05-07T16:10:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 힘 판정 :\n[9] + [4] = [13]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0098215","time":"2026-05-07T16:10:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그냥 몸으로 풀들을 쓰러뜨려가며 새로 길을 내서 길드로 돌아가는 님드.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098216","time":"2026-05-07T16:10:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"역시 가장 빠른 길은 직선거리다!","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098217","time":"2026-05-07T16:10:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"...그대, 뭐하는 거지?\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098218","time":"2026-05-07T16:11:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"뒤에서 그 꼴 바라본다. 하여간 사막 놈들 중에 제정신이 없군.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098219","time":"2026-05-07T16:14:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 길 만들기... \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098220","time":"2026-05-07T16:15:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"그래........... 이 숲 개척자야. 생각이라는 걸 하지는 않은 모양이구나.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098221","time":"2026-05-07T16:16:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"놀라운 사실이지만 그대가 벗지 않은 갑주의 맨 윗부분 안에는 머리라는 게 있네.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098222","time":"2026-05-07T16:17:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n어쩌겠는가. 솔직히 여기서도 길드 건물로 이어지는 길은 모르겠는데 더 도움을 청하기에는 자존심이 상해서 그냥 길을 새로 만들어 버리기로 했다고 말 할 수는...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098223","time":"2026-05-07T16:18:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"없다. 없다...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098224","time":"2026-05-07T16:18:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"어디 가서 사막 출신이라 하지 말아.\"\n\n길 알려주려는 듯 앞장 서서 저벅저벅... 따라오고 있는 게 맞나, 답지 않게 뒤도 돌아본다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098225","time":"2026-05-07T16:18:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"안 오고 뭐하나.\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098226","time":"2026-05-07T16:20:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"자이라를 얌전히 고양이처럼? 따라가는 님드.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098227","time":"2026-05-07T16:20:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고양이가 얌전한가?","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098228","time":"2026-05-07T16:22:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"산딸기 한 줌이 아쉽다 할 처지가 아니었어, 그대. 이럴 줄 알았더라면 나는 더 받아야 했어...\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098229","time":"2026-05-07T16:23:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"농담인지 혼잣말인지, 체념인지. 아무튼 중얼거리며 번번히 님드 확인하는 꼴.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098230","time":"2026-05-07T16:25:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드가 자이라와 가까워지자 아까부터 님드가 계속 내던 속삭이는 소리의 정체가 들릴지도 모르겠다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098231","time":"2026-05-07T16:25:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"스카일라 언어로 된 카카투 신앙의 기도문...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098232","time":"2026-05-07T16:25:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만, 어째서?","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098233","time":"2026-05-07T16:30:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"어디서 사람이 짖나...\"\n\n카카투 기도문 어렴풋이 들려오자 먼산 보며 저벅저벅.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098234","time":"2026-05-07T16:31:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그렇게 숲을 빠져나오는 순간...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098235","time":"2026-05-07T16:31:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"속삭이는 소리가 뚝, 끊긴다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098236","time":"2026-05-07T16:31:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 숲 속에서 들려오는 깊고 어둡고 끔찍하고 불길한 목소리...","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098237","time":"2026-05-07T16:32:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"' 아쉽다... '\n\n\" 조심하시오. 자이라. \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098238","time":"2026-05-07T16:32:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 속삭이는 사제에게 말을 거는 것은 좋지 않소. \"\n\n님드가 속삭임을 멈추는 순간 주변을 비추던 빛이 사라지며 어둠에 잠기고.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098239","time":"2026-05-07T16:33:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"숲속에서 시뻘건 짐승 같은 두 눈이 그들을 노려보다가 훽, 사라진다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098240","time":"2026-05-07T16:33:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 쉼 없이 기도를 하면서 무언가로부터 일행을 지키고 있을 가능성이 높거든. \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098241","time":"2026-05-07T16:48:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"...사제?\"\n\n위아래로 님드 훑어본다. 이 덩치로? 아니, 아까의 길치 이미지가 강하게 남아있는 것이 컸다. 책임이라는 단어와 거리가 먼 건 자신도 마찬가지였지만... 저쪽이 영...","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098242","time":"2026-05-07T16:49:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"......\"\n\n\"...그래.\"\n\n떨떠름하게 고개 끄덕이고, 묘한 표정. 숲으로 시선 잠시 향했다.","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098243","time":"2026-05-07T16:50:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 언젠가 제대로 보답하겠소. \"\n\n길드 건물 쪽으로 저벅저벅 걸어간다.","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098244","time":"2026-05-07T16:51:00+09:00","room":"RP II","name":"자이라","profile":"자이라","identity":"reviewed","type":"dialogue","body":"\"다음에는 길 잃지 말게.\"\n\n손 휘적인다. 뒷모습 빠안히... 빤히...\n\n\"거기서 오른쪽 건물이네. 알지?\"","characters":["P-d5a3db8286da"]},{"id":"RP-II-0098245","time":"2026-05-07T16:54:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098246","time":"2026-05-07T16:54:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 알아. \"","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098247","time":"2026-05-07T16:56:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"사진","characters":[]},{"id":"RP-II-0098248","time":"2026-05-07T16:56:00+09:00","room":"RP II","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f310b84f8f20"]},{"id":"RP-II-0098249","time":"2026-05-07T16:56:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
